def chunk_overlap(text: str, max_len: int, overlap: int) -> list:
    if max_len <= 0 or not text:
        return []

    if overlap < 0:
        overlap = 0

    step = max_len - overlap
    if step <= 0:
        step = 1

    chunks = []
    n = len(text)
    start = 0

    while start < n:
        end = start + max_len
        if end > n:
            end = n
        chunks.append(text[start:end])
        if end == n:
            break
        start += step

    return chunks

